prompt:
You are optimizing a C function for speed.

Write a single C source file that defines

    void matmul(const float *A, const float *B, float *C, int n);

which computes C = A * B for square n x n matrices of single-precision (float) values stored in row-major order, so element (i, j) of A is A[i*n + j]. The three buffers do not overlap. C is not initialized: your function must write every element of C.

Requirements:
- The result must be correct for every positive n, not only for convenient sizes. Results are checked against a reference with a relative tolerance of about 1e-3, so reordering floating-point sums is fine.
- The benchmark runs large matrices (around a thousand rows and columns) and reports the best of several runs, so optimize for large n.
- The file is compiled with gcc and linked, together with a fixed benchmark harness that calls matmul, against the C math library and pthreads. Do not define main. Only the C standard library, libm, pthreads and OpenMP are available.
- You choose the compiler flags. They are passed to gcc as given (for example -O3 or -fopenmp). Flags that set the output file, add include or library paths, or pass options through to the linker are rejected.
- The program is built and run inside a Linux container, not on the machine you are running on. The CPU is not disclosed.
- Optimize for speed on the machine this runs on.

Reply format. Reply with the complete source file in exactly one fenced block:

```c
...
```

followed on its own line by the compiler flags, for example:

FLAGS: -O3 -march=native

Do not write any other code block or any other line starting with FLAGS:.

Below are your attempts so far, oldest first. Each was compiled and run; the observations are measured.

### Attempt 0
FLAGS: -O3 -march=native -fopenmp -funroll-loops
```c
#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 96
#define NC 192

typedef float v8 __attribute__((vector_size(32)));
typedef float v8u __attribute__((vector_size(32), aligned(4)));

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict C, int ldc, int mr, int nr, int first)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
#define ST(r, x0, x1) do { \
            v8u *p = (v8u *)(C + (r) * ldc); \
            if (first) { p[0] = x0; ((v8u *)(C + (r) * ldc + 8))[0] = x1; } \
            else { p[0] += x0; ((v8u *)(C + (r) * ldc + 8))[0] += x1; } \
        } while (0)
        ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
        ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
    } else {
        v8 t[MR][2] __attribute__((aligned(32)));
        t[0][0] = c00; t[0][1] = c01; t[1][0] = c10; t[1][1] = c11;
        t[2][0] = c20; t[2][1] = c21; t[3][0] = c30; t[3][1] = c31;
        t[4][0] = c40; t[4][1] = c41; t[5][0] = c50; t[5][1] = c51;
        const float *tf = (const float *)t;
        for (int i = 0; i < mr; i++) {
            float *cr = C + i * ldc;
            const float *tr = tf + i * NR;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tr[j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tr[j];
        }
    }
}

static void pack_a(const float *A, int n, int i0, int mc, int p0, int kc, float *restrict ap)
{
    for (int ir = 0; ir < mc; ir += MR) {
        int mr = mc - ir < MR ? mc - ir : MR;
        for (int r = 0; r < MR; r++) {
            if (r < mr) {
                const float *src = A + (size_t)(i0 + ir + r) * n + p0;
                for (int k = 0; k < kc; k++) ap[k * MR + r] = src[k];
            } else {
                for (int k = 0; k < kc; k++) ap[k * MR + r] = 0.0f;
            }
        }
        ap += (size_t)MR * kc;
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npan = (n + NR - 1) / NR;
    size_t bsz = (size_t)n * npan * NR * sizeof(float);
    bsz = (bsz + 63) & ~(size_t)63;
    float *Bp = (float *)aligned_alloc(64, bsz);

    int nib = (n + MC - 1) / MC;
    int njb = (n + NC - 1) / NC;
    int nkb = (n + KC - 1) / KC;

    #pragma omp parallel
    {
        float *ap = (float *)aligned_alloc(64, (size_t)MC * KC * sizeof(float));

        /* Pack B: for each k-block p0, panels of kc x NR, zero padded. */
        #pragma omp for collapse(2) schedule(static)
        for (int kb = 0; kb < nkb; kb++) {
            for (int jp = 0; jp < npan; jp++) {
                int p0 = kb * KC;
                int kc = n - p0 < KC ? n - p0 : KC;
                int j0 = jp * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                float *dst = Bp + (size_t)p0 * npan * NR + (size_t)jp * kc * NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(p0 + k) * n + j0;
                    float *d = dst + k * NR;
                    int j = 0;
                    for (; j < nr; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }
        }

        #pragma omp for collapse(2) schedule(dynamic, 1)
        for (int ib = 0; ib < nib; ib++) {
            for (int jb = 0; jb < njb; jb++) {
                int i0 = ib * MC;
                int mc = n - i0 < MC ? n - i0 : MC;
                int j0 = jb * NC;
                int nc = n - j0 < NC ? n - j0 : NC;
                int jp0 = j0 / NR;
                int jp1 = (j0 + nc + NR - 1) / NR;
                for (int kb = 0; kb < nkb; kb++) {
                    int p0 = kb * KC;
                    int kc = n - p0 < KC ? n - p0 : KC;
                    pack_a(A, n, i0, mc, p0, kc, ap);
                    const float *bblk = Bp + (size_t)p0 * npan * NR;
                    for (int jp = jp0; jp < jp1; jp++) {
                        int jj = jp * NR;
                        int nr = n - jj < NR ? n - jj : NR;
                        const float *bp = bblk + (size_t)jp * kc * NR;
                        for (int ir = 0; ir < mc; ir += MR) {
                            int mr = mc - ir < MR ? mc - ir : MR;
                            kernel(kc, ap + (size_t)ir * kc, bp,
                                   C + (size_t)(i0 + ir) * n + jj, n,
                                   mr, nr, kb == 0);
                        }
                    }
                }
            }
        }
        free(ap);
    }
    free(Bp);
}
